#!/usr/bin/env python3
"""
Wording the app needs that the uploaded questionnaires do not contain, part 2.

  * the 33 NOC skill names          (the documents say "Skill 1" ... "Skill 9")
  * the 33 skill definitions        (shown in the "Definition:" tooltip)
  * the eight section titles
  * the language-picker's own strings, which post-date every translation

Same table format as lang8_countries.py:
    English | es | fr | it | pt | ar | zh | hi | tl

The parser is duplicated here on purpose: this file is a standalone script, and
importing a sibling module by bare name is fragile (and flagged by type
checkers) because tools/ is not a package.
"""

CODES = ["es", "fr", "it", "pt", "ar", "zh", "hi", "tl"]


def parse(table: str) -> dict[str, dict[str, str]]:
    out: dict[str, dict[str, str]] = {}
    for line in table.strip().splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        parts = [p.strip() for p in line.split("|")]
        if len(parts) != len(CODES) + 1:
            raise SystemExit(f"bad row ({len(parts)} columns): {line[:60]}")
        en, rest = parts[0], parts[1:]
        if any(not v for v in rest):
            raise SystemExit(f"empty translation: {en}")
        out[en] = dict(zip(CODES, rest))
    return out

